//! Phone durations: `base duration of the sound x context factors`.
//!
//! @generated by tools/fit_durations.py — fitted by least squares (on log duration) to
//! 15945 labelled phones from two speakers of the CMU Arctic corpus. On held-out sentences
//! the hand-written rules this replaced were off by a factor of e^0.40 on average; this model
//! by e^0.36 (the rest is speakers simply not timing a word the same way twice).

use crate::phone::Ph;

/// What the timeline knows about a phone's surroundings.
pub(crate) struct Context {
    pub stress: u8,
    /// False for the weak words (the, of, he, would ...) that are not phrase-final.
    pub is_content: bool,
    /// A word said in full but without an accent of its own: a longer preposition or a
    /// conjunction, or a pronoun at the very end of a phrase.
    pub light: bool,
    pub word_initial: bool,
    pub word_final: bool,
    /// The phone belongs to the last word before a pause.
    pub phrase_final_word: bool,
    /// The phone belongs to the word carrying the phrase's main accent.
    pub nuclear: bool,
    pub n_sylls: usize,
    /// No vowel follows inside the word (last syllable, or its coda).
    pub last_syllable: bool,
    /// Stress of the syllable a consonant leads into (0 if none in this word).
    pub onset_stress: u8,
    /// Neighbouring phones within the phrase (`Ph::SIL` at its edges).
    pub prev: Ph,
    pub next: Ph,
    pub prev_same_word: bool,
    pub next_same_word: bool,
}

/// Duration in ms of a stressed vowel in a one-syllable content word before a voiced
/// consonant, or of a word-medial single consonant.
pub(crate) fn base_ms(ph: Ph) -> f64 {
    match ph {
        Ph::AA => 97.9,
        Ph::AE => 95.0,
        Ph::AH => 67.1,
        Ph::AO => 108.9,
        Ph::AW => 115.5,
        Ph::AX => 48.1,
        Ph::AY => 122.7,
        Ph::B => 55.1,
        Ph::CH => 105.1,
        Ph::D => 46.5,
        Ph::DH => 43.6,
        Ph::EH => 66.6,
        Ph::ER => 99.1,
        Ph::EY => 112.9,
        Ph::F => 76.5,
        Ph::G => 61.4,
        Ph::HH => 52.2,
        Ph::IH => 53.6,
        Ph::IY => 93.4,
        Ph::JH => 89.5,
        Ph::K => 76.5,
        Ph::L => 77.5,
        Ph::M => 68.1,
        Ph::N => 57.4,
        Ph::NG => 81.9,
        Ph::OW => 97.6,
        Ph::OY => 139.1,
        Ph::P => 73.9,
        Ph::R => 64.7,
        Ph::S => 92.9,
        Ph::SH => 117.1,
        Ph::T => 54.0,
        Ph::TH => 75.8,
        Ph::UH => 51.8,
        Ph::UW => 80.3,
        Ph::V => 59.2,
        Ph::W => 66.2,
        Ph::Y => 59.2,
        Ph::Z => 77.4,
        Ph::ZH => 98.1,
        Ph::SIL => 80.0,
    }
}

const V_UNSTRESSED: f64 = 0.690; // unstressed vowel in a content word
const V_SECONDARY: f64 = 0.824; // secondary stress
const V_FUNCTION: f64 = 0.740; // vowel of a (non-final) function word
const V_NUCLEAR: f64 = 1.115; // the phrase's main accent
const V_PHRASE_FINAL_SYLLABLE: f64 = 1.657; // last syllable before a pause
const V_PHRASE_FINAL_WORD: f64 = 1.003; // earlier syllables of the last word
const V_WORD_FINAL_SYLLABLE: f64 = 1.185; // last syllable of a longer word
const V_PHRASE_FINAL_OPEN: f64 = 1.527; // nothing after the vowel at all
const V_BEFORE_VOWEL: f64 = 1.436; // hiatus
const V_BEFORE_LIQUID: f64 = 0.833; // the liquid/glide takes over part of the vowel
const V_WORD_INITIAL: f64 = 1.250; // word starts with this vowel
const V_LIGHT: f64 = 0.842; // a word said in full but not accented ("about", "because")
const V_LIGHT_FINAL: f64 = 0.755; // a pronoun at the very end of a phrase
const C_INITIAL_CONTENT: f64 = 1.192; // first sound of a content word
const C_INITIAL_FUNCTION: f64 = 1.372; // first sound of a function word
const C_FINAL: f64 = 1.173; // last sound of a word
const C_AFTER_CONSONANT: f64 = 0.859; // second member of a cluster
const C_BEFORE_CONSONANT: f64 = 1.087; // first member of a cluster
const C_PHRASE_FINAL: f64 = 1.743; // the very last sound before a pause
const C_PHRASE_FINAL_CODA: f64 = 1.326; // other coda consonants of the last syllable
const C_STRESSED_ONSET: f64 = 1.273; // starts a stressed syllable
const C_FUNCTION: f64 = 0.877; // inside a function word
const C_FLAP: f64 = 0.853; // t/d between vowels before an unstressed syllable
const C_LIGHT: f64 = 0.922; // inside a word said in full but not accented
const C_LIGHT_FINAL: f64 = 0.829; // inside a pronoun at the very end of a phrase

fn is_approximant(ph: Ph) -> bool {
    matches!(ph, Ph::L | Ph::R | Ph::W | Ph::Y)
}

/// Natural duration in milliseconds of `ph` in context `c`, at a normal speaking rate.
pub(crate) fn duration_ms(ph: Ph, c: &Context) -> f64 {
    let mut d = base_ms(ph);
    let phrase_final = c.next == Ph::SIL;
    if ph.is_vowel() {
        d *= match (c.is_content, c.stress) {
            (_, 1) => 1.0,
            (_, 2) => V_SECONDARY,
            (true, _) => V_UNSTRESSED,
            (false, _) => V_FUNCTION,
        };
        if c.nuclear && c.stress == 1 {
            d *= V_NUCLEAR;
        }
        if c.phrase_final_word {
            d *= if c.last_syllable { V_PHRASE_FINAL_SYLLABLE } else { V_PHRASE_FINAL_WORD };
        } else if c.last_syllable && c.n_sylls > 1 {
            d *= V_WORD_FINAL_SYLLABLE;
        }
        if phrase_final {
            d *= V_PHRASE_FINAL_OPEN;
        } else if c.next.is_vowel() {
            d *= V_BEFORE_VOWEL;
        } else if is_approximant(c.next) {
            d *= V_BEFORE_LIQUID;
        }
        if !c.prev_same_word {
            d *= V_WORD_INITIAL;
        }
        if c.light {
            d *= if c.phrase_final_word { V_LIGHT_FINAL } else { V_LIGHT };
        }
    } else {
        let after_consonant = c.prev_same_word && !c.prev.is_vowel();
        let before_consonant = c.next_same_word && !c.next.is_vowel();
        if c.word_initial {
            d *= if c.is_content { C_INITIAL_CONTENT } else { C_INITIAL_FUNCTION };
        } else if c.word_final {
            d *= C_FINAL;
        }
        if after_consonant {
            d *= C_AFTER_CONSONANT;
        }
        if before_consonant {
            d *= C_BEFORE_CONSONANT;
        }
        if c.phrase_final_word && c.last_syllable {
            d *= if phrase_final { C_PHRASE_FINAL } else { C_PHRASE_FINAL_CODA };
        }
        if !c.last_syllable && c.onset_stress == 1 && !before_consonant {
            d *= C_STRESSED_ONSET;
        }
        if !c.is_content {
            d *= C_FUNCTION;
        }
        if matches!(ph, Ph::T | Ph::D)
            && c.prev.is_vowel()
            && c.next.is_vowel()
            && c.onset_stress != 1
            && !c.word_initial
        {
            d *= C_FLAP;
        }
        if c.light {
            d *= if c.phrase_final_word { C_LIGHT_FINAL } else { C_LIGHT };
        }
    }
    d
}
